const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const root = '/bench/repo';
const internal = path.join(root, 'internal');

function walk(dir, files = []) {
  for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, ent.name);
    if (ent.isDirectory()) walk(p, files);
    else if (ent.name.endsWith('.go') && !ent.name.endsWith('_test.go')) files.push(p);
  }
  return files;
}

const decls = [];
for (const file of walk(internal)) {
  const content = fs.readFileSync(file, 'utf8');
  const rel = path.relative(root, file);
  const importPath = 'github.com/usememos/memos/' + path.relative(root, path.dirname(file)).split(path.sep).join('/');
  const pkg = (content.match(/^package (\w+)/m) || [])[1];
  const re = /^func (?:\(([^)]*)\) )?(\w+)\(/gm;
  let m;
  while ((m = re.exec(content)) !== null) {
    const [_, recv, name] = m;
    if (name === 'init') continue;
    const line = content.slice(0, m.index).split('\n').length;
    decls.push({ name, path: rel, line, importPath, pkg, recv: recv ? recv.trim() : null });
  }
}

function grepCount(pattern) {
  try {
    const out = execSync(`grep -r --include='*.go' -E '${pattern.replace(/'/g, "'\\''")}' '${root}'`, { encoding: 'utf8', maxBuffer: 50*1024*1024 });
    const callers = new Set();
    for (const line of out.split('\n').filter(Boolean)) {
      const file = line.split(':')[0];
      if (file.includes('_test.go')) continue;
      callers.add(path.relative(root, file));
    }
    return callers.size;
  } catch { return 0; }
}

const results = [];
for (const d of decls) {
  let fanin = 0;
  if (d.recv) {
    fanin = grepCount(`\\.${d.name}\\(`);
  } else {
    // package func: count pkg.Name( across repo
    fanin = grepCount(`\\.${d.name}\\(`);
    // also count bare calls within same package - harder; add same-package bare name(
    if (fanin === 0) fanin = grepCount(`\\b${d.name}\\(`);
  }
  const sym = d.recv ? `(${d.recv}).${d.name}` : `${d.pkg}.${d.name}`;
  results.push({ fanin, sym, path: d.path, line: d.line, name: d.name, importPath: d.importPath });
}

results.sort((a,b) => b.fanin - a.fanin);
for (const r of results.slice(0, 30)) {
  console.log(`${String(r.fanin).padStart(4)}  ${r.sym}  ${r.path}:${r.line}`);
}
EOF

